const RARE_OR_HIGHER = ["Rare", "Iconic", "Legendary"];

// req()/rarityReq()/pref() -- tiny constructors used by CLIENTS (in
// data-story.js) to build each character's briefs and preferences. They
// live here, not in the engine script, because data-story.js is evaluated
// before the engine script loads: function declarations only hoist within
// their own <script> tag, not across separate ones, so CLIENTS needs these
// to already exist by the time it runs.
function req(attr, value, label) { return { attr, value, label: label || value }; }
function rarityReq(label) { return { attr: "rarity", anyOf: RARE_OR_HIGHER, label: label || "Rare-or-higher" }; }
function pref(attr, value) { return { type: "attr", attr, value }; }

